-- JAGAPADI Core Schema & Master Seed (MariaDB Compatible)
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `activity_log`;
CREATE TABLE `activity_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL,
  `action` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `table_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `record_id` bigint unsigned DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user` (`user_id`) USING BTREE,
  KEY `idx_action` (`action`) USING BTREE,
  KEY `idx_created` (`created_at`) USING BTREE,
  CONSTRAINT `fk_al_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `analisis_produksi_bulanan`;
CREATE TABLE `analisis_produksi_bulanan` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `periode_bulan` int NOT NULL,
  `periode_tahun` int NOT NULL,
  `wilayah_id` int unsigned NOT NULL,
  `total_luas_panen` decimal(15,2) DEFAULT '0.00',
  `total_produksi` decimal(15,2) DEFAULT NULL,
  `avg_produktivitas` decimal(12,4) DEFAULT NULL,
  `perubahan_produksi_pct` decimal(10,2) DEFAULT NULL,
  `faktor_penyebab_utama` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `skor_risiko_cuaca` int DEFAULT '0',
  `skor_risiko_hama` int DEFAULT '0',
  `skor_risiko_total` int DEFAULT '0',
  `avg_curah_hujan_lag1` decimal(10,2) DEFAULT '0.00',
  `total_laporan_hama_lag1` int DEFAULT '0',
  `laporan_hama_berat_lag1` int DEFAULT '0',
  `narasi_otomatis` text COLLATE utf8mb4_unicode_ci,
  `narasi_final` text COLLATE utf8mb4_unicode_ci,
  `data_quality_json` json DEFAULT NULL,
  `source_snapshot_json` json DEFAULT NULL,
  `algorithm_version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2.0.0',
  `status_analisis` enum('draft','published','archived') COLLATE utf8mb4_unicode_ci DEFAULT 'draft',
  `created_by` int unsigned NOT NULL,
  `published_by` int unsigned DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_periode_wilayah` (`periode_bulan`,`periode_tahun`,`wilayah_id`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `analisis_produksi_logs`;
CREATE TABLE `analisis_produksi_logs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `analisis_id` int unsigned NOT NULL,
  `action` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `old_values` text COLLATE utf8mb4_unicode_ci,
  `new_values` text COLLATE utf8mb4_unicode_ci,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `user_id` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `audit_log_wilayah`;
CREATE TABLE `audit_log_wilayah` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `admin_id` int unsigned NOT NULL,
  `tabel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `record_id` int unsigned NOT NULL,
  `aksi` enum('INSERT','UPDATE','DELETE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_lama` json DEFAULT NULL,
  `data_baru` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_admin` (`admin_id`) USING BTREE,
  KEY `idx_tabel_record` (`tabel`,`record_id`) USING BTREE,
  KEY `idx_created` (`created_at`) USING BTREE,
  CONSTRAINT `fk_alw_admin` FOREIGN KEY (`admin_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `backup_master_desa_wareng_41_20260502`;
CREATE TABLE `backup_master_desa_wareng_41_20260502` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kecamatan_id` int unsigned NOT NULL,
  `kode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_desa` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_kode` (`kode`) USING BTREE,
  KEY `idx_kecamatan` (`kecamatan_id`) USING BTREE,
  KEY `idx_nama` (`nama_desa`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `backup_master_kabupaten_fix_nama_kota_mfd_2025_1`;
CREATE TABLE `backup_master_kabupaten_fix_nama_kota_mfd_2025_1` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_kabupaten` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_kode` (`kode`) USING BTREE,
  KEY `idx_nama` (`nama_kabupaten`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `bps_data_anomalies`;
CREATE TABLE `bps_data_anomalies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `data_id` int NOT NULL,
  `field_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value_actual` decimal(15,2) DEFAULT NULL,
  `value_expected_min` decimal(15,2) DEFAULT NULL,
  `value_expected_max` decimal(15,2) DEFAULT NULL,
  `anomaly_type` enum('out_of_range','suspicious','duplicate') COLLATE utf8mb4_unicode_ci DEFAULT 'out_of_range',
  `status` enum('pending','reviewed','resolved') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_data_id` (`data_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bps_scraping_logs`;
CREATE TABLE `bps_scraping_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `action` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `details` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_action_status` (`action`,`status`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `bps_scraping_queue`;
CREATE TABLE `bps_scraping_queue` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tahun` int NOT NULL,
  `kabupaten` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'simulasi',
  `skenario` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'baseline',
  `force_refresh` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('pending','running','completed','failed') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `progress` int DEFAULT '0',
  `result` json DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status_created` (`status`,`created_at`),
  KEY `idx_tahun` (`tahun`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `bps_yearly_summary`;
CREATE TABLE `bps_yearly_summary` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tahun` int NOT NULL,
  `total_kabupaten` int DEFAULT '0',
  `total_luas_panen` decimal(15,2) DEFAULT '0.00',
  `total_produksi_gabah` decimal(15,2) DEFAULT '0.00',
  `total_produksi_beras` decimal(15,2) DEFAULT '0.00',
  `rata_produktivitas` decimal(10,2) DEFAULT '0.00',
  `last_updated` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tahun` (`tahun`),
  KEY `idx_tahun` (`tahun`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `cuaca_angin_jember`;
CREATE TABLE `cuaca_angin_jember` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `id_kecamatan` int DEFAULT NULL,
  `latitude` decimal(8,5) NOT NULL,
  `longitude` decimal(8,5) NOT NULL,
  `tanggal` date NOT NULL,
  `ws10m_ms` decimal(5,2) NOT NULL,
  `ws2m_ms` decimal(5,2) DEFAULT NULL,
  `sumber` varchar(50) DEFAULT 'NASA_POWER',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_wind_loc` (`id_kecamatan`,`tanggal`,`latitude`,`longitude`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `curah_hujan`;
CREATE TABLE `curah_hujan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tanggal` date NOT NULL,
  `lokasi` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Jember',
  `kecamatan_id` int unsigned DEFAULT NULL,
  `kecamatan` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `kode_wilayah` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `curah_hujan` decimal(10,2) NOT NULL,
  `satuan` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'mm',
  `sumber_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `unique_tanggal_lokasi_sumber` (`tanggal`,`lokasi`,`sumber_data`),
  KEY `idx_tanggal` (`tanggal`) USING BTREE,
  KEY `idx_story_rain_period` (`kecamatan_id`,`tanggal`),
  KEY `idx_ch_coords` (`latitude`,`longitude`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `curah_hujan_logs`;
CREATE TABLE `curah_hujan_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `action` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'success',
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `records_processed` int DEFAULT '0',
  `records_success` int DEFAULT '0',
  `records_failed` int DEFAULT '0',
  `execution_time` decimal(10,4) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `data_irigasi`;
CREATE TABLE `data_irigasi` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tanggal` date NOT NULL,
  `daerah_irigasi` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama DI / DAM',
  `kecamatan` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `luas_sawah` decimal(10,2) DEFAULT NULL COMMENT 'Hektar',
  `debit_air` decimal(10,2) DEFAULT NULL COMMENT 'Liter/detik',
  `status_pintu` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Aman / Waspada / Kritis',
  `metode_data` enum('aktual','manual','simulasi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `unique_data` (`tanggal`,`daerah_irigasi`) USING BTREE,
  KEY `idx_tanggal` (`tanggal`) USING BTREE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `data_ksa_bulanan`;
CREATE TABLE `data_ksa_bulanan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tahun` smallint unsigned NOT NULL,
  `bulan` tinyint unsigned NOT NULL,
  `kabupaten_kota` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kode_wilayah` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `luas_panen` decimal(15,4) DEFAULT NULL,
  `produksi_gabah` decimal(15,4) DEFAULT NULL,
  `produksi_beras` decimal(15,4) DEFAULT NULL,
  `produktivitas` decimal(10,4) DEFAULT NULL,
  `status_data` enum('tetap','sementara','potensi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tetap',
  `sumber_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sumber_sheet` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `imported_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ksa` (`tahun`,`bulan`,`kode_wilayah`),
  KEY `idx_tahun_bulan` (`tahun`,`bulan`),
  KEY `idx_kabupaten` (`kabupaten_kota`),
  KEY `idx_kode_wilayah` (`kode_wilayah`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `data_pertanian_bps`;
CREATE TABLE `data_pertanian_bps` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tahun` int NOT NULL,
  `kode_provinsi` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '35',
  `kabupaten_kota` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `kode_wilayah` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `luas_panen` decimal(15,2) NOT NULL DEFAULT '0.00',
  `produksi_gabah` decimal(15,2) NOT NULL DEFAULT '0.00',
  `produksi_beras` decimal(15,2) DEFAULT NULL COMMENT 'dalam ton',
  `produktivitas` decimal(10,2) NOT NULL DEFAULT '0.00',
  `sumber_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sumber_data_type` enum('ksa','resmi_webapi','manual','simulasi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'simulasi',
  `tipe_skenario` enum('baseline','optimis','pesimis') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'baseline',
  `is_validated` tinyint(1) DEFAULT '0',
  `validation_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_bps_source_scenario` (`tahun`,`kode_provinsi`,`kabupaten_kota`,`sumber_data_type`,`tipe_skenario`),
  KEY `idx_bps_tahun` (`tahun`) USING BTREE,
  KEY `idx_bps_kabupaten` (`kabupaten_kota`) USING BTREE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `device_tokens`;
CREATE TABLE `device_tokens` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `token` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `platform` enum('android','ios','web') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'android',
  `user_agent` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_seen_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_device_token` (`token`) USING BTREE,
  KEY `idx_device_tokens_user` (`user_id`) USING BTREE,
  CONSTRAINT `fk_device_tokens_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `evaluasi_akurasi_logs`;
CREATE TABLE `evaluasi_akurasi_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `action` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('success','failed','partial') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `details` json DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_created_at` (`created_at`) USING BTREE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `evaluasi_akurasi_panen`;
CREATE TABLE `evaluasi_akurasi_panen` (
  `id` int NOT NULL AUTO_INCREMENT,
  `periode_bulan` int NOT NULL,
  `periode_tahun` year NOT NULL,
  `wilayah_id` int NOT NULL,
  `nama_wilayah` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `luas_estimasi_daerah` decimal(10,2) NOT NULL DEFAULT '0.00',
  `luas_rilis_bps` decimal(10,2) DEFAULT NULL,
  `deviasi_absolut` decimal(10,2) DEFAULT NULL,
  `persentase_bias` decimal(5,2) DEFAULT NULL,
  `status_akurasi` enum('Sangat Akurat','Perlu Perhatian','Bias Tinggi') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `catatan_analisis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `snapshot_locked` tinyint(1) DEFAULT '0',
  `snapshot_date` date DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `unique_periode_wilayah` (`periode_bulan`,`periode_tahun`,`wilayah_id`) USING BTREE,
  KEY `idx_tahun` (`periode_tahun`) USING BTREE,
  KEY `idx_status` (`status_akurasi`) USING BTREE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `feedback`;
CREATE TABLE `feedback` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `jenis_feedback` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'bug, fitur_baru, peningkatan',
  `judul` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deskripsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `prioritas` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium' COMMENT 'low, medium, high, critical',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'diterima' COMMENT 'diterima, dalam_proses, selesai, ditolak',
  `attachment_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `processed_by` int unsigned DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `vote_count` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_feedback_user_id` (`user_id`) USING BTREE,
  KEY `idx_feedback_status` (`status`) USING BTREE,
  KEY `idx_feedback_jenis` (`jenis_feedback`) USING BTREE,
  KEY `idx_feedback_prioritas` (`prioritas`) USING BTREE,
  KEY `idx_feedback_processed_by` (`processed_by`) USING BTREE,
  KEY `idx_feedback_created_at` (`created_at`) USING BTREE,
  CONSTRAINT `fk_feedback_processor` FOREIGN KEY (`processed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_feedback_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `feedback_status_history`;
CREATE TABLE `feedback_status_history` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `feedback_id` int unsigned NOT NULL,
  `old_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `new_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `changed_by` int unsigned NOT NULL,
