DROP TABLE IF EXISTS `laporan_alat_sarana`;
CREATE TABLE `laporan_alat_sarana` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nomor_laporan` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_id` int unsigned NOT NULL,
  `tanggal` date DEFAULT NULL,
  `kabupaten_id` int unsigned DEFAULT NULL,
  `kecamatan_id` int unsigned DEFAULT NULL,
  `desa_id` int unsigned DEFAULT NULL,
  `lokasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alamat_lengkap` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `jenis_sarana` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_alat` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jumlah` int unsigned DEFAULT NULL,
  `kondisi` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_url` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `status` enum('Draf','Submitted','Diverifikasi','Ditolak','Diarsipkan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Draf',
  `verified_by` int unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `catatan_verifikasi` text COLLATE utf8mb4_unicode_ci,
  `ip_pengirim` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_las_nomor_laporan` (`nomor_laporan`),
  KEY `idx_las_user` (`user_id`),
  KEY `idx_las_status` (`status`),
  KEY `idx_las_tanggal` (`tanggal`),
  KEY `idx_las_kecamatan` (`kecamatan_id`),
  KEY `idx_las_jenis_sarana` (`jenis_sarana`),
  KEY `idx_las_kondisi` (`kondisi`),
  KEY `idx_las_status_tanggal` (`status`,`tanggal`),
  KEY `fk_las_kabupaten` (`kabupaten_id`),
  KEY `fk_las_desa` (`desa_id`),
  KEY `fk_las_verified_by` (`verified_by`),
  CONSTRAINT `fk_las_desa` FOREIGN KEY (`desa_id`) REFERENCES `master_desa` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_las_kabupaten` FOREIGN KEY (`kabupaten_id`) REFERENCES `master_kabupaten` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_las_kecamatan` FOREIGN KEY (`kecamatan_id`) REFERENCES `master_kecamatan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_las_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_las_verified_by` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ck_las_latitude` CHECK (((`latitude` is null) or ((`latitude` >= -(90)) and (`latitude` <= 90)))),
  CONSTRAINT `ck_las_longitude` CHECK (((`longitude` is null) or ((`longitude` >= -(180)) and (`longitude` <= 180))))
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `laporan_cuaca`;
CREATE TABLE `laporan_cuaca` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
