  `desa_id` int unsigned DEFAULT NULL,
  `lokasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alamat_lengkap` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `kondisi_cuaca` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `suhu` decimal(5,1) DEFAULT NULL,
  `kelembaban` decimal(5,1) DEFAULT NULL,
  `curah_hujan` decimal(8,2) DEFAULT NULL,
  `kecepatan_angin` decimal(5,1) DEFAULT NULL,
  `arah_angin` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_url` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_unicode_ci,
