  `verified_by` int unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `catatan_verifikasi` text COLLATE utf8mb4_unicode_ci,
  `ip_pengirim` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lc_nomor_laporan` (`nomor_laporan`),
  KEY `idx_lc_user` (`user_id`),
  KEY `idx_lc_status` (`status`),
  KEY `idx_lc_tanggal` (`tanggal`),
  KEY `idx_lc_kecamatan` (`kecamatan_id`),
  KEY `idx_lc_kondisi_cuaca` (`kondisi_cuaca`),
