) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `master_desa`;
CREATE TABLE `master_desa` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kecamatan_id` int unsigned NOT NULL,
  `kode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_desa` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_kode` (`kode`) USING BTREE,
  KEY `idx_kecamatan` (`kecamatan_id`) USING BTREE,
  KEY `idx_nama` (`nama_desa`) USING BTREE,
  CONSTRAINT `fk_desa_kecamatan` FOREIGN KEY (`kecamatan_id`) REFERENCES `master_kecamatan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `master_jenis_laporan`;
CREATE TABLE `master_jenis_laporan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deskripsi` text COLLATE utf8mb4_unicode_ci,
  `fields_json` json NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_kode` (`kode`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `master_kabupaten`;
CREATE TABLE `master_kabupaten` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_kabupaten` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_kode` (`kode`) USING BTREE,
  KEY `idx_nama` (`nama_kabupaten`) USING BTREE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `master_kabupaten_by_province`;
CREATE TABLE `master_kabupaten_by_province` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode_provinsi` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kode_kabupaten` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_kabupaten` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipe_kabupaten` enum('kabupaten','kota') COLLATE utf8mb4_unicode_ci DEFAULT 'kabupaten',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_prov_kab` (`kode_provinsi`,`kode_kabupaten`),
  KEY `idx_provinsi` (`kode_provinsi`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `master_kecamatan`;
CREATE TABLE `master_kecamatan` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kabupaten_id` int unsigned NOT NULL,
  `kode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_kecamatan` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_kode` (`kode`) USING BTREE,
  KEY `idx_kabupaten` (`kabupaten_id`) USING BTREE,
  KEY `idx_nama` (`nama_kecamatan`) USING BTREE,
  CONSTRAINT `fk_kecamatan_kabupaten` FOREIGN KEY (`kabupaten_id`) REFERENCES `master_kabupaten` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `master_opt`;
CREATE TABLE `master_opt` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode_opt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_opt` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_ilmiah` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_lokal` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis` enum('hama','penyakit','gulma') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_karantina` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tingkat_bahaya` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kategori` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kingdom` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `filum` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kelas` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ordo` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `famili` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `genus` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `etl_acuan` decimal(10,2) DEFAULT NULL,
  `satuan_etl` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_url` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deskripsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `rekomendasi` text COLLATE utf8mb4_unicode_ci,
  `referensi` text COLLATE utf8mb4_unicode_ci,
  `aktif` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_nama_opt` (`nama_opt`) USING BTREE,
  UNIQUE KEY `uk_master_opt_kode_opt` (`kode_opt`),
  KEY `idx_jenis` (`jenis`) USING BTREE,
  KEY `idx_aktif` (`aktif`) USING BTREE,
  KEY `idx_kode_opt` (`kode_opt`) USING BTREE,
  KEY `idx_status_karantina` (`status_karantina`) USING BTREE,
  KEY `idx_tingkat_bahaya` (`tingkat_bahaya`) USING BTREE,
  KEY `idx_kategori` (`kategori`) USING BTREE,
  FULLTEXT KEY `ft_nama` (`nama_opt`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `master_provinsi`;
CREATE TABLE `master_provinsi` (
  `kode_provinsi` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_provinsi` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint DEFAULT '1',
  PRIMARY KEY (`kode_provinsi`),
  KEY `idx_nama` (`nama_provinsi`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `nomor_laporan_counter`;
CREATE TABLE `nomor_laporan_counter` (
  `prefix` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggal` date NOT NULL,
  `counter` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`prefix`,`tanggal`) USING BTREE,
  KEY `idx_tanggal_counter` (`tanggal`,`counter`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'laporan_submitted, laporan_verified, laporan_rejected, laporan_resubmitted, laporan_archived',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'JSON payload: entity, laporan_id, nomor_laporan, status, web_path, api_path',
  `read_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_created` (`user_id`,`created_at`) USING BTREE,
  KEY `idx_user_unread` (`user_id`,`read_at`) USING BTREE,
  KEY `idx_type` (`type`) USING BTREE,
  CONSTRAINT `fk_notifications_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `pembacaan_sensor`;
CREATE TABLE `pembacaan_sensor` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `sensor_id` int unsigned NOT NULL,
  `nilai` decimal(10,2) DEFAULT NULL,
  `status_pembacaan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `waktu_baca` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_ps_sensor_id` (`sensor_id`) USING BTREE,
  KEY `idx_ps_waktu` (`waktu_baca`) USING BTREE,
  CONSTRAINT `fk_ps_sensor` FOREIGN KEY (`sensor_id`) REFERENCES `sensor_pengairan` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `pengairan_otomatis`;
CREATE TABLE `pengairan_otomatis` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `irigasi_id` int unsigned DEFAULT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `triggered_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `ended_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_po_irigasi` (`irigasi_id`) USING BTREE,
  KEY `idx_po_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `produksi_gabah`;
CREATE TABLE `produksi_gabah` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kecamatan_id` int unsigned NOT NULL,
  `tahun` int NOT NULL,
  `bulan` tinyint unsigned DEFAULT NULL,
  `luas_panen` decimal(15,2) NOT NULL DEFAULT '0.00',
  `produksi_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'draft, pending, verified, rejected',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_produksi_kecamatan` (`kecamatan_id`) USING BTREE,
  KEY `idx_produksi_tahun` (`tahun`) USING BTREE,
  KEY `idx_produksi_status` (`status`) USING BTREE,
  KEY `idx_story_production_period` (`kecamatan_id`,`tahun`,`bulan`,`status`),
  CONSTRAINT `fk_produksi_kecamatan` FOREIGN KEY (`kecamatan_id`) REFERENCES `master_kecamatan` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `schema_migrations`;
CREATE TABLE `schema_migrations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch` int unsigned NOT NULL,
  `executed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_migration` (`migration`) USING BTREE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `scraping_job_queue`;
CREATE TABLE `scraping_job_queue` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `job_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parameters` json NOT NULL,
  `status` enum('pending','running','completed','failed') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `progress` int DEFAULT '0',
  `result` json DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_type_status` (`job_type`,`status`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `sensor_pengairan`;
CREATE TABLE `sensor_pengairan` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kode_sensor` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipe_sensor` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nilai_min` decimal(10,2) DEFAULT NULL,
  `nilai_max` decimal(10,2) DEFAULT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Aktif',
  `last_reading_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_sensor_kode` (`kode_sensor`) USING BTREE,
  KEY `idx_sensor_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `tags`;
CREATE TABLE `tags` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `nama_tag` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deskripsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `warna` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#007bff',
  `usage_count` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tags_nama` (`nama_tag`) USING BTREE,
  KEY `idx_tags_usage` (`usage_count`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_lengkap` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('admin','petugas','operator','statistisi','viewer') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'petugas',
  `aktif` tinyint(1) NOT NULL DEFAULT '1',
  `ksa` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'KSA komoditas group assignment for petugas (KSA Padi / KSA Jagung)',
  `must_change_password` tinyint(1) NOT NULL DEFAULT '0',
  `token_version` int unsigned NOT NULL DEFAULT '0',
  `last_password_change_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_username` (`username`) USING BTREE,
  UNIQUE KEY `uk_email` (`email`) USING BTREE,
  KEY `idx_role` (`role`) USING BTREE,
  KEY `idx_aktif` (`aktif`) USING BTREE,
  KEY `idx_users_ksa` (`ksa`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `usulan_opt`;
CREATE TABLE `usulan_opt` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `nama_nasional` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_lokal` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jenis` enum('hama','penyakit','gulma') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'hama',
  `komoditas` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_ditemukan` date DEFAULT NULL,
  `kabupaten_id` int unsigned DEFAULT NULL,
  `kecamatan_id` int unsigned DEFAULT NULL,
  `desa_id` int unsigned DEFAULT NULL,
  `alamat_lokasi` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `bagian_terserang` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pola_gejala` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estimasi_terdampak` decimal(12,2) DEFAULT NULL,
  `satuan_terdampak` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tingkat_keyakinan` enum('Rendah','Sedang','Tinggi') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sumber_identifikasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `ciri_ciri` text COLLATE utf8mb4_unicode_ci,
  `wilayah` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_url` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Draf','Menunggu Review','Perlu Perbaikan','Disetujui','Digabungkan','Ditolak Permanen') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Menunggu Review',
  `master_opt_id` int unsigned DEFAULT NULL,
  `catatan_review` text COLLATE utf8mb4_unicode_ci,
  `reviewed_by` int unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_usulan_opt_user_status` (`user_id`,`status`),
  KEY `idx_usulan_opt_status_created` (`status`,`created_at`),
  KEY `fk_usulan_opt_master` (`master_opt_id`),
  KEY `fk_usulan_opt_reviewer` (`reviewed_by`),
  KEY `idx_usulan_opt_nama_nasional` (`nama_nasional`),
  KEY `idx_usulan_opt_nama_lokal` (`nama_lokal`),
  KEY `idx_usulan_opt_created_at` (`created_at`),
  KEY `idx_usulan_opt_submitted` (`submitted_at`),
  KEY `fk_usulan_opt_kabupaten` (`kabupaten_id`),
  KEY `fk_usulan_opt_kecamatan` (`kecamatan_id`),
  KEY `fk_usulan_opt_desa` (`desa_id`),
  KEY `idx_usulan_opt_deleted_at` (`deleted_at`),
  KEY `fk_usulan_opt_deleted_by` (`deleted_by`),
  KEY `idx_uo_user_deleted_created` (`user_id`,`deleted_at`,`created_at`),
  CONSTRAINT `fk_usulan_opt_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_usulan_opt_desa` FOREIGN KEY (`desa_id`) REFERENCES `master_desa` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_usulan_opt_kabupaten` FOREIGN KEY (`kabupaten_id`) REFERENCES `master_kabupaten` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_usulan_opt_kecamatan` FOREIGN KEY (`kecamatan_id`) REFERENCES `master_kecamatan` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_usulan_opt_master` FOREIGN KEY (`master_opt_id`) REFERENCES `master_opt` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_usulan_opt_reviewer` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_usulan_opt_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_usulan_opt_estimasi` CHECK (((`estimasi_terdampak` is null) or (`estimasi_terdampak` >= 0))),
  CONSTRAINT `ck_usulan_opt_lat` CHECK (((`latitude` is null) or ((`latitude` >= -(90)) and (`latitude` <= 90)))),
  CONSTRAINT `ck_usulan_opt_lng` CHECK (((`longitude` is null) or ((`longitude` >= -(180)) and (`longitude` <= 180))))
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `usulan_opt_photos`;
CREATE TABLE `usulan_opt_photos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `usulan_opt_id` bigint unsigned NOT NULL,
  `file_path` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size_bytes` int unsigned DEFAULT NULL,
  `checksum` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `caption` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_uop_usulan_created` (`usulan_opt_id`,`created_at`),
  KEY `idx_uop_checksum` (`checksum`),
  KEY `fk_uop_creator` (`created_by`),
  CONSTRAINT `fk_uop_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_uop_usulan` FOREIGN KEY (`usulan_opt_id`) REFERENCES `usulan_opt` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `usulan_opt_status_history`;
CREATE TABLE `usulan_opt_status_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `usulan_opt_id` bigint unsigned NOT NULL,
  `from_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `changed_by` int unsigned DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_uosh_usulan_created` (`usulan_opt_id`,`created_at`),
  KEY `idx_uosh_changed_created` (`changed_by`,`created_at`),
  CONSTRAINT `fk_uosh_actor` FOREIGN KEY (`changed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_uosh_usulan` FOREIGN KEY (`usulan_opt_id`) REFERENCES `usulan_opt` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
