(1, 'bibit_baru', 'Penanaman Bibit Baru', 'Laporan penanaman bibit baru di lahan pertanian', '[{\"name\": \"nama_varietas\", \"type\": \"text\", \"label\": \"Nama Varietas\", \"required\": true}, {\"name\": \"jumlah_bibit\", \"type\": \"number\", \"label\": \"Jumlah Bibit\", \"required\": true}, {\"name\": \"sumber_bibit\", \"type\": \"text\", \"label\": \"Sumber Bibit\", \"required\": false}]', 1, '2026-08-03 13:36:35'),
(2, 'rumah_kaca', 'Rumah Kaca', 'Laporan kondisi dan aktivitas rumah kaca', '[{\"name\": \"jumlah_unit\", \"type\": \"number\", \"label\": \"Jumlah Unit\", \"required\": true}, {\"name\": \"luas_m2\", \"type\": \"number\", \"label\": \"Luas (m²)\", \"required\": false}, {\"name\": \"komoditas\", \"type\": \"text\", \"label\": \"Komoditas\", \"required\": false}]', 1, '2026-08-03 13:36:35'),
(3, 'panen', 'Panen', 'Laporan kegiatan panen pertanian', '[{\"name\": \"komoditas\", \"type\": \"text\", \"label\": \"Komoditas\", \"required\": true}, {\"name\": \"luas_ha\", \"type\": \"number\", \"label\": \"Luas Panen (Ha)\", \"required\": false}, {\"name\": \"estimasi_ton\", \"type\": \"number\", \"label\": \"Estimasi Ton\", \"required\": false}]', 1, '2026-08-03 13:36:35'),
(4, 'bantuan_alsintan', 'Bantuan Alsintan', 'Laporan penerimaan bantuan alat dan mesin pertanian', '[{\"name\": \"nama_alat\", \"type\": \"text\", \"label\": \"Nama Alat\", \"required\": true}, {\"name\": \"jumlah\", \"type\": \"number\", \"label\": \"Jumlah\", \"required\": false}, {\"name\": \"sumber_bantuan\", \"type\": \"text\", \"label\": \"Sumber Bantuan\", \"required\": false}]', 1, '2026-08-03 13:36:35'),
(5, 'kerusakan_cuaca', 'Kerusakan Cuaca', 'Laporan kerusakan akibat cuaca ekstrem', '[{\"name\": \"jenis_cuaca\", \"type\": \"text\", \"label\": \"Jenis Cuaca\", \"required\": true}, {\"name\": \"luas_terdampak_ha\", \"type\": \"number\", \"label\": \"Luas Terdampak (Ha)\", \"required\": false}]', 1, '2026-08-03 13:36:35'),
(6, 'gangguan_sosial', 'Gangguan Sosial', 'Laporan gangguan aktivitas manusia atau hewan ternak terhadap kegiatan dan lahan pertanian.', '[{\"name\": \"nama_gangguan\", \"type\": \"text\", \"label\": \"Nama Gangguan\", \"required\": true}, {\"name\": \"sumber_gangguan\", \"type\": \"text\", \"label\": \"Sumber Gangguan\", \"required\": false}, {\"name\": \"komoditas\", \"type\": \"text\", \"label\": \"Komoditas Terdampak\", \"required\": true}, {\"name\": \"luas_terdampak_ha\", \"type\": \"number\", \"label\": \"Luas Terdampak (Ha)\", \"required\": false}]', 1, '2026-08-24 15:31:13'),
(7, 'faktor_abiotik', 'Faktor Abiotik', 'Laporan gangguan tanaman akibat kondisi non-hayati seperti kekeringan, genangan, suhu, atau kondisi tanah.', '[{\"name\": \"nama_faktor\", \"type\": \"text\", \"label\": \"Nama Faktor Abiotik\", \"required\": true}, {\"name\": \"komoditas\", \"type\": \"text\", \"label\": \"Komoditas Terdampak\", \"required\": true}, {\"name\": \"fase_tanaman\", \"type\": \"text\", \"label\": \"Fase Tanaman\", \"required\": false}, {\"name\": \"luas_terdampak_ha\", \"type\": \"number\", \"label\": \"Luas Terdampak (Ha)\", \"required\": false}]', 1, '2026-08-24 15:31:13'),
(8, 'bencana_cuaca', 'Bencana Cuaca', 'Laporan kerusakan pertanian akibat angin kencang, puting beliung, hujan ekstrem, banjir, atau kejadian cuaca lainnya.', '[{\"name\": \"jenis_bencana\", \"type\": \"text\", \"label\": \"Jenis Bencana Cuaca\", \"required\": true}, {\"name\": \"komoditas\", \"type\": \"text\", \"label\": \"Komoditas Terdampak\", \"required\": true}, {\"name\": \"tingkat_kerusakan\", \"type\": \"text\", \"label\": \"Tingkat Kerusakan\", \"required\": false}, {\"name\": \"luas_terdampak_ha\", \"type\": \"number\", \"label\": \"Luas Terdampak (Ha)\", \"required\": false}]', 1, '2026-08-24 15:31:13'),
(9, 'gangguan_fisiologis', 'Gangguan Fisiologis', 'Laporan gangguan pertumbuhan tanaman akibat ketidakseimbangan hara, keracunan unsur, pH, atau kondisi fisiologis lainnya.', '[{\"name\": \"nama_gangguan\", \"type\": \"text\", \"label\": \"Nama Gangguan Fisiologis\", \"required\": true}, {\"name\": \"komoditas\", \"type\": \"text\", \"label\": \"Komoditas Terdampak\", \"required\": true}, {\"name\": \"faktor_pemicu\", \"type\": \"text\", \"label\": \"Faktor Pemicu\", \"required\": false}, {\"name\": \"luas_terdampak_ha\", \"type\": \"number\", \"label\": \"Luas Terdampak (Ha)\", \"required\": false}]', 1, '2026-08-24 15:31:13');
